INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-43-01', 'lesson-essential-verbs-a1-43', 1, 'sentence', 'Our team always wins at home.', 'Nosso time sempre ganha em casa.', '/aʊər tiːm ˈɔːlweɪz wɪnz æt hoʊm/', '"Win" = ganhar (jogo, prêmio). Dinheiro de salário é "earn".', '[]'::jsonb, '[{"surface":"Our","pos":"determiner","ipa":"/aʊər/","gloss":"nosso"},{"surface":"team","pos":"noun","ipa":"/tiːm/","gloss":"time, equipe"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"wins","pos":"verb","ipa":"/wɪnz/","gloss":"ganha"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-43-02', 'lesson-essential-verbs-a1-43', 2, 'sentence', 'She won the first prize.', 'Ela ganhou o primeiro prêmio.', '/ʃiː wʌn ðə fɜːrst praɪz/', 'Passado irregular: "won" /wʌn/.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"won","pos":"verb","ipa":"/wʌn/","gloss":"ganhou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"prize","pos":"noun","ipa":"/praɪz/","gloss":"prêmio"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-43-03', 'lesson-essential-verbs-a1-43', 3, 'sentence', 'You will win next time.', 'Você vai ganhar da próxima vez.', '/juː wɪl wɪn nɛkst taɪm/', 'Futuro com "will".', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"win","pos":"noun","ipa":"/wɪn/","gloss":"vitória, conquista"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-43-04', 'lesson-essential-verbs-a1-43', 4, 'sentence', 'They have won three games in a row.', 'Eles ganharam três jogos seguidos.', '/ðeɪ hæv wʌn θriː ɡeɪmz ɪn ə roʊ/', '"In a row" = seguidos. Particípio: "won".', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"won","pos":"verb","ipa":"/wʌn/","gloss":"ganhou"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"},{"surface":"games","pos":"noun","ipa":"/ɡeɪmz/","gloss":"jogos"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"row","pos":"noun","ipa":"/roʊ/","gloss":"fileira (in a row = seguidos)"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-43-05', 'lesson-essential-verbs-a1-43', 5, 'sentence', 'My mother teaches math.', 'Minha mãe ensina matemática.', '/maɪ ˈmʌðər ˈtiːtʃɪz mæθ/', '"Teach" = ensinar. Com he/she/it: "teaches".', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"mother","pos":"noun","ipa":"/ˈmʌðər/","gloss":"mãe"},{"surface":"teaches","pos":"verb","ipa":"/ˈtiːtʃɪz/","gloss":"ensina"},{"surface":"math","pos":"noun","ipa":"/mæθ/","gloss":"matemática"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-43-06', 'lesson-essential-verbs-a1-43', 6, 'sentence', 'He taught me how to drive.', 'Ele me ensinou a dirigir.', '/hiː tɔːt miː haʊ tuː draɪv/', 'Passado irregular: "taught" /tɔːt/.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"taught","pos":"verb","ipa":"/tɔːt/","gloss":"ensinou"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"how","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"drive","pos":"verb","ipa":"/draɪv/","gloss":"dirigir"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-43-07', 'lesson-essential-verbs-a1-43', 7, 'sentence', 'I''ll teach you a trick.', 'Vou te ensinar um truque.', '/aɪl tiːtʃ juː ə trɪk/', '"Teach" + pessoa + coisa.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"teach","pos":"verb","ipa":"/tiːtʃ/","gloss":"ensinar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"trick","pos":"noun","ipa":"/trɪk/","gloss":"truque"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-43-08', 'lesson-essential-verbs-a1-43', 8, 'sentence', 'She has taught here for twenty years.', 'Ela dá aula aqui há vinte anos.', '/ʃiː hæz tɔːt hɪr fɔːr ˈtwɛnti jɪrz/', 'Present perfect + "for".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"taught","pos":"verb","ipa":"/tɔːt/","gloss":"ensinou"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"twenty","pos":"numeral","ipa":"/ˈtwɛnti/","gloss":"vinte"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-44-01', 'lesson-essential-verbs-a1-44', 1, 'sentence', 'The hotel offers free breakfast.', 'O hotel oferece café da manhã grátis.', '/ðə hoʊˈtɛl ˈɔːfərz friː ˈbrɛkfəst/', '"Offer" = oferecer.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"hotel","pos":"noun","ipa":"/hoʊˈtɛl/","gloss":"hotel"},{"surface":"offers","pos":"verb","ipa":"/ˈɔːfərz/","gloss":"oferece"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"},{"surface":"breakfast","pos":"noun","ipa":"/ˈbrɛkfəst/","gloss":"café da manhã"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-44-02', 'lesson-essential-verbs-a1-44', 2, 'sentence', 'He offered to help.', 'Ele se ofereceu para ajudar.', '/hiː ˈɔːfərd tuː hɛlp/', '"Offer to" + verbo = se oferecer para.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"offered","pos":"verb","ipa":"/ˈɔːfərd/","gloss":"ofereceu"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-44-03', 'lesson-essential-verbs-a1-44', 3, 'sentence', 'Will they offer you the job?', 'Eles vão te oferecer a vaga?', '/wɪl ðeɪ ˈɔːfər juː ðə dʒɑːb/', 'Pergunta com "will".', '[]'::jsonb, '[{"surface":"Will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"offer","pos":"noun","ipa":"/ˈɔːfər/","gloss":"oferta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-44-04', 'lesson-essential-verbs-a1-44', 4, 'sentence', 'They have offered me a better salary.', 'Me ofereceram um salário melhor.', '/ðeɪ hæv ˈɔːfərd miː ə ˈbɛtər ˈsæləri/', 'Present perfect: novidade recente.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"offered","pos":"verb","ipa":"/ˈɔːfərd/","gloss":"ofereceu"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"better","pos":"adjective","ipa":"/ˈbɛtər/","gloss":"melhor"},{"surface":"salary","pos":"noun","ipa":"/ˈsæləri/","gloss":"salário"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-44-05', 'lesson-essential-verbs-a1-44', 5, 'sentence', 'I remember your face.', 'Lembro do seu rosto.', '/aɪ rɪˈmɛmbər jʊr feɪs/', '"Remember" sem "of": "remember your face".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"remember","pos":"verb","ipa":"/rɪˈmɛmbər/","gloss":"lembrar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"face","pos":"noun","ipa":"/feɪs/","gloss":"rosto"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-44-06', 'lesson-essential-verbs-a1-44', 6, 'sentence', 'I didn''t remember her name.', 'Não lembrei o nome dela.', '/aɪ ˈdɪdənt rɪˈmɛmbər hɜːr neɪm/', 'Passado negativo com "didn''t".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"remember","pos":"verb","ipa":"/rɪˈmɛmbər/","gloss":"lembrar"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-44-07', 'lesson-essential-verbs-a1-44', 7, 'sentence', 'I''ll remember this day forever.', 'Vou lembrar deste dia para sempre.', '/aɪl rɪˈmɛmbər ðɪs deɪ fərˈɛvər/', '"Forever" = para sempre.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"remember","pos":"verb","ipa":"/rɪˈmɛmbər/","gloss":"lembrar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"},{"surface":"forever","pos":"adverb","ipa":"/fərˈɛvər/","gloss":"para sempre"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-44-08', 'lesson-essential-verbs-a1-44', 8, 'sentence', 'Have you remembered to lock the door?', 'Você lembrou de trancar a porta?', '/hæv juː rɪˈmɛmbərd tuː lɑːk ðə dɔːr/', '"Remember to" + verbo = lembrar de fazer.', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"remembered","pos":"verb","ipa":"/rɪˈmɛmbərd/","gloss":"lembrou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"lock","pos":"verb","ipa":"/lɑːk/","gloss":"trancar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-45-01', 'lesson-essential-verbs-a1-45', 1, 'sentence', 'I love this city.', 'Adoro esta cidade.', '/aɪ lʌv ðɪs ˈsɪti/', '"Love" também é "adorar" coisas.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"love","pos":"verb","ipa":"/lʌv/","gloss":"amar, adorar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-45-02', 'lesson-essential-verbs-a1-45', 2, 'sentence', 'She loved the gift.', 'Ela adorou o presente.', '/ʃiː lʌvd ðə ɡɪft/', 'Passado regular: "loved".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"loved","pos":"verb","ipa":"/lʌvd/","gloss":"amou, adorou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"gift","pos":"noun","ipa":"/ɡɪft/","gloss":"presente"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-45-03', 'lesson-essential-verbs-a1-45', 3, 'sentence', 'You''ll love the food there.', 'Você vai adorar a comida de lá.', '/juːl lʌv ðə fuːd ðɛr/', 'Previsão com "will".', '[]'::jsonb, '[{"surface":"You''ll","pos":"pronoun","ipa":"/juːl/","gloss":"você vai (you will)"},{"surface":"love","pos":"verb","ipa":"/lʌv/","gloss":"amar, adorar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"food","pos":"noun","ipa":"/fuːd/","gloss":"comida"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-45-04', 'lesson-essential-verbs-a1-45', 4, 'sentence', 'I''ve always loved music.', 'Sempre adorei música.', '/aɪv ˈɔːlweɪz lʌvd ˈmjuːzɪk/', 'Present perfect + "always".', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"loved","pos":"verb","ipa":"/lʌvd/","gloss":"amou, adorou"},{"surface":"music","pos":"noun","ipa":"/ˈmjuːzɪk/","gloss":"música"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-45-05', 'lesson-essential-verbs-a1-45', 5, 'sentence', 'We''re considering a new car.', 'Estamos pensando em um carro novo.', '/wɪr kənˈsɪdərɪŋ ə nuː kɑːr/', '"Consider" = considerar, pensar em.', '[]'::jsonb, '[{"surface":"We''re","pos":"pronoun","ipa":"/wɪr/","gloss":"nós estamos"},{"surface":"considering","pos":"verb","ipa":"/kənˈsɪdərɪŋ/","gloss":"considerando"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-45-06', 'lesson-essential-verbs-a1-45', 6, 'sentence', 'He considered all the options.', 'Ele considerou todas as opções.', '/hiː kənˈsɪdərd ɔːl ðə ˈɑːpʃənz/', 'Passado regular.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"considered","pos":"verb","ipa":"/kənˈsɪdərd/","gloss":"considerou"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"options","pos":"noun","ipa":"/ˈɑːpʃənz/","gloss":"opções"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-45-07', 'lesson-essential-verbs-a1-45', 7, 'sentence', 'Will you consider my offer?', 'Você vai considerar minha oferta?', '/wɪl juː kənˈsɪdər maɪ ˈɔːfər/', 'Pedido educado.', '[]'::jsonb, '[{"surface":"Will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"consider","pos":"verb","ipa":"/kənˈsɪdər/","gloss":"considerar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"offer","pos":"noun","ipa":"/ˈɔːfər/","gloss":"oferta"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-45-08', 'lesson-essential-verbs-a1-45', 8, 'sentence', 'Have you considered moving abroad?', 'Você já pensou em morar fora?', '/hæv juː kənˈsɪdərd ˈmuːvɪŋ əˈbrɔːd/', '"Consider" + verbo com "-ing".', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"considered","pos":"verb","ipa":"/kənˈsɪdərd/","gloss":"considerou"},{"surface":"moving","pos":"verb","ipa":"/ˈmuːvɪŋ/","gloss":"mudar-se"},{"surface":"abroad","pos":"adverb","ipa":"/əˈbrɔːd/","gloss":"no exterior"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-46-01', 'lesson-essential-verbs-a1-46', 1, 'sentence', 'He appears in many movies.', 'Ele aparece em muitos filmes.', '/hiː əˈpɪrz ɪn ˈmɛni ˈmuːviz/', '"Appear" = aparecer.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"appears","pos":"verb","ipa":"/əˈpɪrz/","gloss":"aparece"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"movies","pos":"noun","ipa":"/ˈmuːviz/","gloss":"filmes"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-46-02', 'lesson-essential-verbs-a1-46', 2, 'sentence', 'A message appeared on the screen.', 'Apareceu uma mensagem na tela.', '/ə ˈmɛsɪdʒ əˈpɪrd ɑːn ðə skriːn/', 'Passado regular.', '[]'::jsonb, '[{"surface":"A","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"message","pos":"noun","ipa":"/ˈmɛsɪdʒ/","gloss":"mensagem"},{"surface":"appeared","pos":"verb","ipa":"/əˈpɪrd/","gloss":"apareceu"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"screen","pos":"noun","ipa":"/skriːn/","gloss":"tela"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-46-03', 'lesson-essential-verbs-a1-46', 3, 'sentence', 'The results will appear tomorrow.', 'Os resultados vão aparecer amanhã.', '/ðə rɪˈzʌlts wɪl əˈpɪr təˈmɑːroʊ/', 'Futuro com "will".', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"results","pos":"noun","ipa":"/rɪˈzʌlts/","gloss":"resultados"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"appear","pos":"verb","ipa":"/əˈpɪr/","gloss":"aparecer"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-46-04', 'lesson-essential-verbs-a1-46', 4, 'sentence', 'It has appeared in the news.', 'Isso apareceu no noticiário.', '/ɪt hæz əˈpɪrd ɪn ðə nuːz/', 'Present perfect.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"appeared","pos":"verb","ipa":"/əˈpɪrd/","gloss":"apareceu"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"news","pos":"noun","ipa":"/nuːz/","gloss":"notícia(s)"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-46-05', 'lesson-essential-verbs-a1-46', 5, 'sentence', 'I buy fruit at the market.', 'Compro fruta na feira.', '/aɪ baɪ fruːt æt ðə ˈmɑːrkɪt/', '"Buy" = comprar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"buy","pos":"verb","ipa":"/baɪ/","gloss":"comprar"},{"surface":"fruit","pos":"noun","ipa":"/fruːt/","gloss":"fruta"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"market","pos":"noun","ipa":"/ˈmɑːrkɪt/","gloss":"mercado, feira"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-46-06', 'lesson-essential-verbs-a1-46', 6, 'sentence', 'We bought a new sofa.', 'Compramos um sofá novo.', '/wiː bɔːt ə nuː ˈsoʊfə/', 'Passado irregular: "bought" /bɔːt/.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"bought","pos":"verb","ipa":"/bɔːt/","gloss":"comprou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"sofa","pos":"noun","ipa":"/ˈsoʊfə/","gloss":"sofá"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-46-07', 'lesson-essential-verbs-a1-46', 7, 'sentence', 'I''ll buy you a drink.', 'Te pago uma bebida.', '/aɪl baɪ juː ə drɪŋk/', '"Buy someone a drink" = pagar uma bebida.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"buy","pos":"verb","ipa":"/baɪ/","gloss":"comprar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"drink","pos":"verb","ipa":"/drɪŋk/","gloss":"beber"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-46-08', 'lesson-essential-verbs-a1-46', 8, 'sentence', 'I''ve already bought the tickets.', 'Já comprei os ingressos.', '/aɪv ɔːlˈrɛdi bɔːt ðə ˈtɪkɪts/', '"Already" = já.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"already","pos":"adverb","ipa":"/ɔːlˈrɛdi/","gloss":"já"},{"surface":"bought","pos":"verb","ipa":"/bɔːt/","gloss":"comprou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"tickets","pos":"noun","ipa":"/ˈtɪkɪts/","gloss":"ingressos"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-47-01', 'lesson-essential-verbs-a1-47', 1, 'sentence', 'I wait for the bus every morning.', 'Espero o ônibus toda manhã.', '/aɪ weɪt fɔːr ðə bʌs ˈɛvri ˈmɔːrnɪŋ/', '"Wait for" + pessoa ou coisa.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wait","pos":"noun","ipa":"/weɪt/","gloss":"espera; esperar"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-47-02', 'lesson-essential-verbs-a1-47', 2, 'sentence', 'We waited for an hour.', 'Esperamos uma hora.', '/wiː ˈweɪtɪd fɔːr ən ˈaʊər/', 'Passado regular: "waited".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"waited","pos":"verb","ipa":"/ˈweɪtɪd/","gloss":"esperou"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-47-03', 'lesson-essential-verbs-a1-47', 3, 'sentence', 'I''ll wait here.', 'Vou esperar aqui.', '/aɪl weɪt hɪr/', 'Decisão na hora com "will".', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"wait","pos":"noun","ipa":"/weɪt/","gloss":"espera; esperar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-47-04', 'lesson-essential-verbs-a1-47', 4, 'sentence', 'I''ve waited for this moment.', 'Esperei por este momento.', '/aɪv ˈweɪtɪd fɔːr ðɪs ˈmoʊmənt/', 'Present perfect: expectativa até agora.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"waited","pos":"verb","ipa":"/ˈweɪtɪd/","gloss":"esperou"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"moment","pos":"noun","ipa":"/ˈmoʊmənt/","gloss":"momento"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-47-05', 'lesson-essential-verbs-a1-47', 5, 'sentence', 'They serve breakfast until ten.', 'Eles servem café da manhã até as dez.', '/ðeɪ sɜːrv ˈbrɛkfəst ənˈtɪl tɛn/', '"Serve" = servir.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"serve","pos":"verb","ipa":"/sɜːrv/","gloss":"servir"},{"surface":"breakfast","pos":"noun","ipa":"/ˈbrɛkfəst/","gloss":"café da manhã"},{"surface":"until","pos":"conjunction","ipa":"/ənˈtɪl/","gloss":"até"},{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-47-06', 'lesson-essential-verbs-a1-47', 6, 'sentence', 'Dinner was served at eight.', 'O jantar foi servido às oito.', '/ˈdɪnər wɑːz sɜːrvd æt eɪt/', 'Voz passiva: "was served".', '[]'::jsonb, '[{"surface":"Dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"served","pos":"verb","ipa":"/sɜːrvd/","gloss":"servido"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-47-07', 'lesson-essential-verbs-a1-47', 7, 'sentence', 'We will serve drinks at the party.', 'Vamos servir bebidas na festa.', '/wiː wɪl sɜːrv drɪŋks æt ðə ˈpɑːrti/', 'Futuro com "will".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"serve","pos":"verb","ipa":"/sɜːrv/","gloss":"servir"},{"surface":"drinks","pos":"verb","ipa":"/drɪŋks/","gloss":"bebe"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"party","pos":"noun","ipa":"/ˈpɑːrti/","gloss":"festa"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-47-08', 'lesson-essential-verbs-a1-47', 8, 'sentence', 'He has served in the army.', 'Ele serviu no exército.', '/hiː hæz sɜːrvd ɪn ðə ˈɑːrmi/', 'Present perfect: experiência de vida.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"served","pos":"verb","ipa":"/sɜːrvd/","gloss":"servido"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"army","pos":"noun","ipa":"/ˈɑːrmi/","gloss":"exército"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-48-01', 'lesson-essential-verbs-a1-48', 1, 'verb_forms', 'win won won', 'ganhar', '/wɪn wʌn wʌn/', 'Base "win" · passado e particípio "won" /wʌn/.', '[]'::jsonb, '[{"surface":"win","pos":"noun","ipa":"/wɪn/","gloss":"vitória, conquista"},{"surface":"won","pos":"verb","ipa":"/wʌn/","gloss":"ganhou"},{"surface":"won","pos":"verb","ipa":"/wʌn/","gloss":"ganhou"}]'::jsonb, 'She won the first prize.', 'Ela ganhou o primeiro prêmio.'),
  ('unit-essential-verbs-a1-48-02', 'lesson-essential-verbs-a1-48', 2, 'verb_forms', 'teach taught taught', 'ensinar', '/tiːtʃ tɔːt tɔːt/', 'Base "teach" · passado e particípio "taught".', '[]'::jsonb, '[{"surface":"teach","pos":"verb","ipa":"/tiːtʃ/","gloss":"ensinar"},{"surface":"taught","pos":"verb","ipa":"/tɔːt/","gloss":"ensinou"},{"surface":"taught","pos":"verb","ipa":"/tɔːt/","gloss":"ensinou"}]'::jsonb, 'He taught me how to drive.', 'Ele me ensinou a dirigir.'),
  ('unit-essential-verbs-a1-48-03', 'lesson-essential-verbs-a1-48', 3, 'verb_forms', 'offer offered offered', 'oferecer', '/ˈɔːfər ˈɔːfərd ˈɔːfərd/', 'Regular.', '[]'::jsonb, '[{"surface":"offer","pos":"noun","ipa":"/ˈɔːfər/","gloss":"oferta"},{"surface":"offered","pos":"verb","ipa":"/ˈɔːfərd/","gloss":"ofereceu"},{"surface":"offered","pos":"verb","ipa":"/ˈɔːfərd/","gloss":"ofereceu"}]'::jsonb, 'He offered to help.', 'Ele se ofereceu para ajudar.'),
  ('unit-essential-verbs-a1-48-04', 'lesson-essential-verbs-a1-48', 4, 'verb_forms', 'remember remembered remembered', 'lembrar', '/rɪˈmɛmbər rɪˈmɛmbərd rɪˈmɛmbərd/', 'Regular.', '[]'::jsonb, '[{"surface":"remember","pos":"verb","ipa":"/rɪˈmɛmbər/","gloss":"lembrar"},{"surface":"remembered","pos":"verb","ipa":"/rɪˈmɛmbərd/","gloss":"lembrou"},{"surface":"remembered","pos":"verb","ipa":"/rɪˈmɛmbərd/","gloss":"lembrou"}]'::jsonb, 'I didn''t remember her name.', 'Não lembrei o nome dela.'),
  ('unit-essential-verbs-a1-48-05', 'lesson-essential-verbs-a1-48', 5, 'verb_forms', 'love loved loved', 'amar, adorar', '/lʌv lʌvd lʌvd/', 'Regular.', '[]'::jsonb, '[{"surface":"love","pos":"verb","ipa":"/lʌv/","gloss":"amar, adorar"},{"surface":"loved","pos":"verb","ipa":"/lʌvd/","gloss":"amou, adorou"},{"surface":"loved","pos":"verb","ipa":"/lʌvd/","gloss":"amou, adorou"}]'::jsonb, 'She loved the gift.', 'Ela adorou o presente.'),
  ('unit-essential-verbs-a1-48-06', 'lesson-essential-verbs-a1-48', 6, 'verb_forms', 'consider considered considered', 'considerar', '/kənˈsɪdər kənˈsɪdərd kənˈsɪdərd/', 'Regular.', '[]'::jsonb, '[{"surface":"consider","pos":"verb","ipa":"/kənˈsɪdər/","gloss":"considerar"},{"surface":"considered","pos":"verb","ipa":"/kənˈsɪdərd/","gloss":"considerou"},{"surface":"considered","pos":"verb","ipa":"/kənˈsɪdərd/","gloss":"considerou"}]'::jsonb, 'He considered all the options.', 'Ele considerou todas as opções.'),
  ('unit-essential-verbs-a1-48-07', 'lesson-essential-verbs-a1-48', 7, 'verb_forms', 'appear appeared appeared', 'aparecer', '/əˈpɪr əˈpɪrd əˈpɪrd/', 'Regular.', '[]'::jsonb, '[{"surface":"appear","pos":"verb","ipa":"/əˈpɪr/","gloss":"aparecer"},{"surface":"appeared","pos":"verb","ipa":"/əˈpɪrd/","gloss":"apareceu"},{"surface":"appeared","pos":"verb","ipa":"/əˈpɪrd/","gloss":"apareceu"}]'::jsonb, 'A message appeared on the screen.', 'Apareceu uma mensagem na tela.'),
  ('unit-essential-verbs-a1-48-08', 'lesson-essential-verbs-a1-48', 8, 'verb_forms', 'buy bought bought', 'comprar', '/baɪ bɔːt bɔːt/', 'Base "buy" · passado e particípio "bought".', '[]'::jsonb, '[{"surface":"buy","pos":"verb","ipa":"/baɪ/","gloss":"comprar"},{"surface":"bought","pos":"verb","ipa":"/bɔːt/","gloss":"comprou"},{"surface":"bought","pos":"verb","ipa":"/bɔːt/","gloss":"comprou"}]'::jsonb, 'We bought a new sofa.', 'Compramos um sofá novo.'),
  ('unit-essential-verbs-a1-48-09', 'lesson-essential-verbs-a1-48', 9, 'verb_forms', 'wait waited waited', 'esperar', '/weɪt ˈweɪtɪd ˈweɪtɪd/', 'Regular.', '[]'::jsonb, '[{"surface":"wait","pos":"noun","ipa":"/weɪt/","gloss":"espera; esperar"},{"surface":"waited","pos":"verb","ipa":"/ˈweɪtɪd/","gloss":"esperou"},{"surface":"waited","pos":"verb","ipa":"/ˈweɪtɪd/","gloss":"esperou"}]'::jsonb, 'We waited for an hour.', 'Esperamos uma hora.'),
  ('unit-essential-verbs-a1-48-10', 'lesson-essential-verbs-a1-48', 10, 'verb_forms', 'serve served served', 'servir', '/sɜːrv sɜːrvd sɜːrvd/', 'Regular.', '[]'::jsonb, '[{"surface":"serve","pos":"verb","ipa":"/sɜːrv/","gloss":"servir"},{"surface":"served","pos":"verb","ipa":"/sɜːrvd/","gloss":"servido"},{"surface":"served","pos":"verb","ipa":"/sɜːrvd/","gloss":"servido"}]'::jsonb, 'Dinner was served at eight.', 'O jantar foi servido às oito.')
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-49-01', 'lesson-essential-verbs-a1-49', 1, 'sentence', 'Plants die without water.', 'Plantas morrem sem água.', '/plænts daɪ wɪˈðaʊt ˈwɔːtər/', '"Die" = morrer. Verdade geral no presente.', '[]'::jsonb, '[{"surface":"Plants","pos":"noun","ipa":"/plænts/","gloss":"plantas"},{"surface":"die","pos":"verb","ipa":"/daɪ/","gloss":"morrer"},{"surface":"without","pos":"preposition","ipa":"/wɪˈðaʊt/","gloss":"sem"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-49-02', 'lesson-essential-verbs-a1-49', 2, 'sentence', 'My grandfather died last year.', 'Meu avô faleceu no ano passado.', '/maɪ ˈɡrænfɑːðər daɪd læst jɪr/', 'Passado regular: "died".', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"grandfather","pos":"noun","ipa":"/ˈɡrænfɑːðər/","gloss":"avô"},{"surface":"died","pos":"verb","ipa":"/daɪd/","gloss":"morreu"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-49-03', 'lesson-essential-verbs-a1-49', 3, 'sentence', 'My phone will die soon.', 'Meu celular vai descarregar logo.', '/maɪ foʊn wɪl daɪ suːn/', 'Informal: "die" = acabar a bateria.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"die","pos":"verb","ipa":"/daɪ/","gloss":"morrer"},{"surface":"soon","pos":"adverb","ipa":"/suːn/","gloss":"logo"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-49-04', 'lesson-essential-verbs-a1-49', 4, 'sentence', 'The old tree has died.', 'A árvore velha morreu.', '/ðə oʊld triː hæz daɪd/', 'Present perfect: resultado atual.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"tree","pos":"noun","ipa":"/triː/","gloss":"árvore"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"died","pos":"verb","ipa":"/daɪd/","gloss":"morreu"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-49-05', 'lesson-essential-verbs-a1-49', 5, 'sentence', 'I send emails all day.', 'Mando e-mails o dia todo.', '/aɪ sɛnd ˈiːmeɪlz ɔːl deɪ/', '"Send" = enviar, mandar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"send","pos":"verb","ipa":"/sɛnd/","gloss":"enviar, mandar"},{"surface":"emails","pos":"noun","ipa":"/ˈiːmeɪlz/","gloss":"e-mails"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-49-06', 'lesson-essential-verbs-a1-49', 6, 'sentence', 'She sent me a photo.', 'Ela me mandou uma foto.', '/ʃiː sɛnt miː ə ˈfoʊtoʊ/', 'Passado irregular: "sent".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"sent","pos":"verb","ipa":"/sɛnt/","gloss":"enviou"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"photo","pos":"noun","ipa":"/ˈfoʊtoʊ/","gloss":"foto"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-49-07', 'lesson-essential-verbs-a1-49', 7, 'sentence', 'I''ll send you the address.', 'Te mando o endereço.', '/aɪl sɛnd juː ðə ˈædrɛs/', '"Send" + pessoa + coisa.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"send","pos":"verb","ipa":"/sɛnd/","gloss":"enviar, mandar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"address","pos":"noun","ipa":"/ˈædrɛs/","gloss":"endereço"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-49-08', 'lesson-essential-verbs-a1-49', 8, 'sentence', 'Have you sent the package?', 'Você já enviou o pacote?', '/hæv juː sɛnt ðə ˈpækɪdʒ/', 'Particípio: "sent".', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"sent","pos":"verb","ipa":"/sɛnt/","gloss":"enviou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"package","pos":"noun","ipa":"/ˈpækɪdʒ/","gloss":"pacote"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-50-01', 'lesson-essential-verbs-a1-50', 1, 'sentence', 'I expect good results.', 'Espero bons resultados.', '/aɪ ɪkˈspɛkt ɡʊd rɪˈzʌlts/', '"Expect" = esperar que aconteça; "wait" = aguardar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"expect","pos":"verb","ipa":"/ɪkˈspɛkt/","gloss":"esperar (expectativa)"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"results","pos":"noun","ipa":"/rɪˈzʌlts/","gloss":"resultados"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-50-02', 'lesson-essential-verbs-a1-50', 2, 'sentence', 'We didn''t expect so many people.', 'Não esperávamos tanta gente.', '/wiː ˈdɪdənt ɪkˈspɛkt soʊ ˈmɛni ˈpiːpəl/', 'Passado negativo.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"expect","pos":"verb","ipa":"/ɪkˈspɛkt/","gloss":"esperar (expectativa)"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-50-03', 'lesson-essential-verbs-a1-50', 3, 'sentence', 'The weather will be better than expected.', 'O tempo vai ser melhor do que o esperado.', '/ðə ˈwɛðər wɪl biː ˈbɛtər ðæn ɪkˈspɛktɪd/', '"Than expected" = do que o esperado.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"weather","pos":"noun","ipa":"/ˈwɛðər/","gloss":"tempo, clima"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"better","pos":"adjective","ipa":"/ˈbɛtər/","gloss":"melhor"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"expected","pos":"verb","ipa":"/ɪkˈspɛktɪd/","gloss":"esperado"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-50-04', 'lesson-essential-verbs-a1-50', 4, 'sentence', 'I''ve been expecting you.', 'Eu estava te esperando.', '/aɪv bɪn ɪkˈspɛktɪŋ juː/', 'Present perfect contínuo com "expect".', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"expecting","pos":"verb","ipa":"/ɪkˈspɛktɪŋ/","gloss":"esperando"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-50-05', 'lesson-essential-verbs-a1-50', 5, 'sentence', 'Birds build nests in spring.', 'Pássaros constroem ninhos na primavera.', '/bɜːrdz bɪld nɛsts ɪn sprɪŋ/', '"Build" = construir.', '[]'::jsonb, '[{"surface":"Birds","pos":"noun","ipa":"/bɜːrdz/","gloss":"pássaros"},{"surface":"build","pos":"verb","ipa":"/bɪld/","gloss":"construir"},{"surface":"nests","pos":"noun","ipa":"/nɛsts/","gloss":"ninhos"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"spring","pos":"noun","ipa":"/sprɪŋ/","gloss":"primavera"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-50-06', 'lesson-essential-verbs-a1-50', 6, 'sentence', 'They built a new school.', 'Construíram uma escola nova.', '/ðeɪ bɪlt ə nuː skuːl/', 'Passado irregular: "built".', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"built","pos":"verb","ipa":"/bɪlt/","gloss":"construiu"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"school","pos":"noun","ipa":"/skuːl/","gloss":"escola"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-50-07', 'lesson-essential-verbs-a1-50', 7, 'sentence', 'We will build a better team.', 'Vamos construir um time melhor.', '/wiː wɪl bɪld ə ˈbɛtər tiːm/', 'Futuro com "will".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"build","pos":"verb","ipa":"/bɪld/","gloss":"construir"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"better","pos":"adjective","ipa":"/ˈbɛtər/","gloss":"melhor"},{"surface":"team","pos":"noun","ipa":"/tiːm/","gloss":"time, equipe"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-50-08', 'lesson-essential-verbs-a1-50', 8, 'sentence', 'The city has built new bike lanes.', 'A cidade construiu novas ciclovias.', '/ðə ˈsɪti hæz bɪlt nuː baɪk leɪnz/', '"Bike lane" = ciclovia.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"built","pos":"verb","ipa":"/bɪlt/","gloss":"construiu"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"bike","pos":"noun","ipa":"/baɪk/","gloss":"bicicleta"},{"surface":"lanes","pos":"noun","ipa":"/leɪnz/","gloss":"faixas, pistas"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-51-01', 'lesson-essential-verbs-a1-51', 1, 'sentence', 'I usually stay home on Sundays.', 'Geralmente fico em casa aos domingos.', '/aɪ ˈjuːʒuəli steɪ hoʊm ɑːn ˈsʌndeɪz/', '"Stay home" = ficar em casa.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"stay","pos":"verb","ipa":"/steɪ/","gloss":"ficar"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Sundays","pos":"proper noun","ipa":"/ˈsʌndeɪz/","gloss":"domingos"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-51-02', 'lesson-essential-verbs-a1-51', 2, 'sentence', 'We stayed at a small hotel.', 'Ficamos num hotel pequeno.', '/wiː steɪd æt ə smɔːl hoʊˈtɛl/', '"Stay at" = hospedar-se em.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"stayed","pos":"verb","ipa":"/steɪd/","gloss":"ficou"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"hotel","pos":"noun","ipa":"/hoʊˈtɛl/","gloss":"hotel"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-51-03', 'lesson-essential-verbs-a1-51', 3, 'sentence', 'I''ll stay until the end.', 'Vou ficar até o fim.', '/aɪl steɪ ənˈtɪl ðə ɛnd/', '"Until" = até.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"stay","pos":"verb","ipa":"/steɪ/","gloss":"ficar"},{"surface":"until","pos":"conjunction","ipa":"/ənˈtɪl/","gloss":"até"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"end","pos":"noun","ipa":"/ɛnd/","gloss":"fim, final"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-51-04', 'lesson-essential-verbs-a1-51', 4, 'sentence', 'She has stayed with us since Monday.', 'Ela está com a gente desde segunda.', '/ʃiː hæz steɪd wɪð ʌs sɪns ˈmʌndeɪ/', 'Present perfect + "since".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"stayed","pos":"verb","ipa":"/steɪd/","gloss":"ficou"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"since","pos":"preposition","ipa":"/sɪns/","gloss":"desde"},{"surface":"Monday","pos":"proper noun","ipa":"/ˈmʌndeɪ/","gloss":"segunda-feira"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-51-05', 'lesson-essential-verbs-a1-51', 5, 'sentence', 'Leaves fall in autumn.', 'As folhas caem no outono.', '/liːvz fɔːl ɪn ˈɔːtəm/', '"Fall" = cair.', '[]'::jsonb, '[{"surface":"Leaves","pos":"verb","ipa":"/liːvz/","gloss":"sai, parte"},{"surface":"fall","pos":"noun","ipa":"/fɔːl/","gloss":"outono"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"autumn","pos":"noun","ipa":"/ˈɔːtəm/","gloss":"outono"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-51-06', 'lesson-essential-verbs-a1-51', 6, 'sentence', 'I fell off my bike.', 'Caí da bicicleta.', '/aɪ fɛl ɔːf maɪ baɪk/', 'Passado irregular: "fell". "Fall off" = cair de cima de.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"fell","pos":"verb","ipa":"/fɛl/","gloss":"caiu"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bike","pos":"noun","ipa":"/baɪk/","gloss":"bicicleta"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-51-07', 'lesson-essential-verbs-a1-51', 7, 'sentence', 'Be careful, you''ll fall.', 'Cuidado, você vai cair.', '/biː ˈkɛrfəl juːl fɔːl/', 'Aviso com "will".', '[]'::jsonb, '[{"surface":"Be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"careful","pos":"adjective","ipa":"/ˈkɛrfəl/","gloss":"cuidadoso"},{"surface":"you''ll","pos":"pronoun","ipa":"/juːl/","gloss":"você vai (you will)"},{"surface":"fall","pos":"noun","ipa":"/fɔːl/","gloss":"outono"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-51-08', 'lesson-essential-verbs-a1-51', 8, 'sentence', 'Prices have fallen this month.', 'Os preços caíram este mês.', '/ˈpraɪsɪz hæv ˈfɔːlən ðɪs mʌnθ/', 'Particípio irregular: "fallen".', '[]'::jsonb, '[{"surface":"Prices","pos":"noun","ipa":"/ˈpraɪsɪz/","gloss":"preços"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"fallen","pos":"verb","ipa":"/ˈfɔːlən/","gloss":"caído"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-52-01', 'lesson-essential-verbs-a1-52', 1, 'sentence', 'I cut my hair every month.', 'Corto o cabelo todo mês.', '/aɪ kʌt maɪ hɛr ˈɛvri mʌnθ/', '"Cut" = cortar. As três formas são iguais.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"cut","pos":"verb","ipa":"/kʌt/","gloss":"cortar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"hair","pos":"noun","ipa":"/hɛr/","gloss":"cabelo"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-52-02', 'lesson-essential-verbs-a1-52', 2, 'sentence', 'I cut my finger yesterday.', 'Cortei o dedo ontem.', '/aɪ kʌt maɪ ˈfɪŋɡər ˈjɛstərdeɪ/', 'Passado igual à base: "cut".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"cut","pos":"verb","ipa":"/kʌt/","gloss":"cortar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"finger","pos":"noun","ipa":"/ˈfɪŋɡər/","gloss":"dedo (da mão)"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-52-03', 'lesson-essential-verbs-a1-52', 3, 'sentence', 'They''ll cut the budget.', 'Vão cortar o orçamento.', '/ðeɪl kʌt ðə ˈbʌdʒɪt/', 'Futuro com "will".', '[]'::jsonb, '[{"surface":"They''ll","pos":"pronoun","ipa":"/ðeɪl/","gloss":"eles vão (they will)"},{"surface":"cut","pos":"verb","ipa":"/kʌt/","gloss":"cortar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"budget","pos":"noun","ipa":"/ˈbʌdʒɪt/","gloss":"orçamento"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-52-04', 'lesson-essential-verbs-a1-52', 4, 'sentence', 'I''ve cut down on sugar.', 'Diminuí o açúcar.', '/aɪv kʌt daʊn ɑːn ˈʃʊɡər/', '"Cut down on" = reduzir o consumo.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"cut","pos":"verb","ipa":"/kʌt/","gloss":"cortar"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"sugar","pos":"noun","ipa":"/ˈʃʊɡər/","gloss":"açúcar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-52-05', 'lesson-essential-verbs-a1-52', 5, 'sentence', 'I can''t reach the top shelf.', 'Não alcanço a prateleira de cima.', '/aɪ kænt riːtʃ ðə tɑːp ʃɛlf/', '"Reach" = alcançar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"reach","pos":"verb","ipa":"/riːtʃ/","gloss":"alcançar, chegar a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"top","pos":"adjective","ipa":"/tɑːp/","gloss":"principal, máximo"},{"surface":"shelf","pos":"noun","ipa":"/ʃɛlf/","gloss":"prateleira"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-52-06', 'lesson-essential-verbs-a1-52', 6, 'sentence', 'We reached the hotel at midnight.', 'Chegamos ao hotel à meia-noite.', '/wiː riːtʃt ðə hoʊˈtɛl æt ˈmɪdnaɪt/', '"Reach" = chegar a (sem "to").', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"reached","pos":"verb","ipa":"/riːtʃt/","gloss":"alcançou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"hotel","pos":"noun","ipa":"/hoʊˈtɛl/","gloss":"hotel"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"midnight","pos":"noun","ipa":"/ˈmɪdnaɪt/","gloss":"meia-noite"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-52-07', 'lesson-essential-verbs-a1-52', 7, 'sentence', 'You''ll reach your goal.', 'Você vai atingir sua meta.', '/juːl riːtʃ jʊr ɡoʊl/', '"Reach a goal" = atingir a meta.', '[]'::jsonb, '[{"surface":"You''ll","pos":"pronoun","ipa":"/juːl/","gloss":"você vai (you will)"},{"surface":"reach","pos":"verb","ipa":"/riːtʃ/","gloss":"alcançar, chegar a"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"goal","pos":"noun","ipa":"/ɡoʊl/","gloss":"meta"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-52-08', 'lesson-essential-verbs-a1-52', 8, 'sentence', 'Sales have reached a record.', 'As vendas atingiram um recorde.', '/seɪlz hæv riːtʃt ə ˈrɛkərd/', 'Present perfect.', '[]'::jsonb, '[{"surface":"Sales","pos":"noun","ipa":"/seɪlz/","gloss":"vendas"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"reached","pos":"verb","ipa":"/riːtʃt/","gloss":"alcançou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"record","pos":"noun","ipa":"/ˈrɛkərd/","gloss":"recorde"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-53-01', 'lesson-essential-verbs-a1-53', 1, 'sentence', 'This spray kills mosquitoes.', 'Este spray mata mosquitos.', '/ðɪs spreɪ kɪlz məˈskiːtoʊz/', '"Kill" = matar.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"spray","pos":"noun","ipa":"/spreɪ/","gloss":"spray"},{"surface":"kills","pos":"verb","ipa":"/kɪlz/","gloss":"mata"},{"surface":"mosquitoes","pos":"noun","ipa":"/məˈskiːtoʊz/","gloss":"mosquitos"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-53-02', 'lesson-essential-verbs-a1-53', 2, 'sentence', 'The storm killed the plants.', 'A tempestade matou as plantas.', '/ðə stɔːrm kɪld ðə plænts/', 'Passado regular: "killed".', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"storm","pos":"noun","ipa":"/stɔːrm/","gloss":"tempestade"},{"surface":"killed","pos":"verb","ipa":"/kɪld/","gloss":"matou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"plants","pos":"noun","ipa":"/plænts/","gloss":"plantas"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-53-03', 'lesson-essential-verbs-a1-53', 3, 'sentence', 'My feet are killing me.', 'Meus pés estão me matando.', '/maɪ fiːt ɑːr ˈkɪlɪŋ miː/', 'Informal: "killing me" = doendo muito.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"feet","pos":"noun","ipa":"/fiːt/","gloss":"pés"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"killing","pos":"verb","ipa":"/ˈkɪlɪŋ/","gloss":"matando"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-53-04', 'lesson-essential-verbs-a1-53', 4, 'sentence', 'We have an hour to kill.', 'Temos uma hora para matar.', '/wiː hæv ən ˈaʊər tuː kɪl/', '"Kill time" = passar o tempo.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"kill","pos":"verb","ipa":"/kɪl/","gloss":"matar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-53-05', 'lesson-essential-verbs-a1-53', 5, 'sentence', 'Please remain seated.', 'Por favor, permaneçam sentados.', '/pliːz rɪˈmeɪn ˈsiːtɪd/', '"Remain" = permanecer. Formal (avião, teatro).', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"remain","pos":"verb","ipa":"/rɪˈmeɪn/","gloss":"permanecer"},{"surface":"seated","pos":"adjective","ipa":"/ˈsiːtɪd/","gloss":"sentado"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-53-06', 'lesson-essential-verbs-a1-53', 6, 'sentence', 'He remained calm.', 'Ele se manteve calmo.', '/hiː rɪˈmeɪnd kɑːm/', 'Passado regular: "remained".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"remained","pos":"verb","ipa":"/rɪˈmeɪnd/","gloss":"permaneceu"},{"surface":"calm","pos":"adjective","ipa":"/kɑːm/","gloss":"calmo"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-53-07', 'lesson-essential-verbs-a1-53', 7, 'sentence', 'The store will remain closed on Monday.', 'A loja vai permanecer fechada na segunda.', '/ðə stɔːr wɪl rɪˈmeɪn kloʊzd ɑːn ˈmʌndeɪ/', 'Formal.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"remain","pos":"verb","ipa":"/rɪˈmeɪn/","gloss":"permanecer"},{"surface":"closed","pos":"verb","ipa":"/kloʊzd/","gloss":"fechou, fechado"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Monday","pos":"proper noun","ipa":"/ˈmʌndeɪ/","gloss":"segunda-feira"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-53-08', 'lesson-essential-verbs-a1-53', 8, 'sentence', 'Prices have remained stable.', 'Os preços permaneceram estáveis.', '/ˈpraɪsɪz hæv rɪˈmeɪnd ˈsteɪbəl/', 'Present perfect.', '[]'::jsonb, '[{"surface":"Prices","pos":"noun","ipa":"/ˈpraɪsɪz/","gloss":"preços"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"remained","pos":"verb","ipa":"/rɪˈmeɪnd/","gloss":"permaneceu"},{"surface":"stable","pos":"adjective","ipa":"/ˈsteɪbəl/","gloss":"estável"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-54-01', 'lesson-essential-verbs-a1-54', 1, 'verb_forms', 'die died died', 'morrer', '/daɪ daɪd daɪd/', 'Regular.', '[]'::jsonb, '[{"surface":"die","pos":"verb","ipa":"/daɪ/","gloss":"morrer"},{"surface":"died","pos":"verb","ipa":"/daɪd/","gloss":"morreu"},{"surface":"died","pos":"verb","ipa":"/daɪd/","gloss":"morreu"}]'::jsonb, 'My grandfather died last year.', 'Meu avô faleceu no ano passado.'),
  ('unit-essential-verbs-a1-54-02', 'lesson-essential-verbs-a1-54', 2, 'verb_forms', 'send sent sent', 'enviar', '/sɛnd sɛnt sɛnt/', 'Base "send" · passado e particípio "sent".', '[]'::jsonb, '[{"surface":"send","pos":"verb","ipa":"/sɛnd/","gloss":"enviar, mandar"},{"surface":"sent","pos":"verb","ipa":"/sɛnt/","gloss":"enviou"},{"surface":"sent","pos":"verb","ipa":"/sɛnt/","gloss":"enviou"}]'::jsonb, 'She sent me a photo.', 'Ela me mandou uma foto.'),
  ('unit-essential-verbs-a1-54-03', 'lesson-essential-verbs-a1-54', 3, 'verb_forms', 'expect expected expected', 'esperar (expectativa)', '/ɪkˈspɛkt ɪkˈspɛktɪd ɪkˈspɛktɪd/', 'Regular.', '[]'::jsonb, '[{"surface":"expect","pos":"verb","ipa":"/ɪkˈspɛkt/","gloss":"esperar (expectativa)"},{"surface":"expected","pos":"verb","ipa":"/ɪkˈspɛktɪd/","gloss":"esperado"},{"surface":"expected","pos":"verb","ipa":"/ɪkˈspɛktɪd/","gloss":"esperado"}]'::jsonb, 'We didn''t expect so many people.', 'Não esperávamos tanta gente.'),
  ('unit-essential-verbs-a1-54-04', 'lesson-essential-verbs-a1-54', 4, 'verb_forms', 'build built built', 'construir', '/bɪld bɪlt bɪlt/', 'Base "build" · passado e particípio "built".', '[]'::jsonb, '[{"surface":"build","pos":"verb","ipa":"/bɪld/","gloss":"construir"},{"surface":"built","pos":"verb","ipa":"/bɪlt/","gloss":"construiu"},{"surface":"built","pos":"verb","ipa":"/bɪlt/","gloss":"construiu"}]'::jsonb, 'They built a new school.', 'Construíram uma escola nova.'),
  ('unit-essential-verbs-a1-54-05', 'lesson-essential-verbs-a1-54', 5, 'verb_forms', 'stay stayed stayed', 'ficar', '/steɪ steɪd steɪd/', 'Regular.', '[]'::jsonb, '[{"surface":"stay","pos":"verb","ipa":"/steɪ/","gloss":"ficar"},{"surface":"stayed","pos":"verb","ipa":"/steɪd/","gloss":"ficou"},{"surface":"stayed","pos":"verb","ipa":"/steɪd/","gloss":"ficou"}]'::jsonb, 'We stayed at a small hotel.', 'Ficamos num hotel pequeno.'),
  ('unit-essential-verbs-a1-54-06', 'lesson-essential-verbs-a1-54', 6, 'verb_forms', 'fall fell fallen', 'cair', '/fɔːl fɛl ˈfɔːlən/', 'Base "fall" · passado "fell" · particípio "fallen".', '[]'::jsonb, '[{"surface":"fall","pos":"noun","ipa":"/fɔːl/","gloss":"outono"},{"surface":"fell","pos":"verb","ipa":"/fɛl/","gloss":"caiu"},{"surface":"fallen","pos":"verb","ipa":"/ˈfɔːlən/","gloss":"caído"}]'::jsonb, 'I fell off my bike.', 'Caí da bicicleta.'),
  ('unit-essential-verbs-a1-54-07', 'lesson-essential-verbs-a1-54', 7, 'verb_forms', 'cut cut cut', 'cortar', '/kʌt kʌt kʌt/', 'As três formas são iguais.', '[]'::jsonb, '[{"surface":"cut","pos":"verb","ipa":"/kʌt/","gloss":"cortar"},{"surface":"cut","pos":"verb","ipa":"/kʌt/","gloss":"cortar"},{"surface":"cut","pos":"verb","ipa":"/kʌt/","gloss":"cortar"}]'::jsonb, 'I cut my finger yesterday.', 'Cortei o dedo ontem.'),
  ('unit-essential-verbs-a1-54-08', 'lesson-essential-verbs-a1-54', 8, 'verb_forms', 'reach reached reached', 'alcançar', '/riːtʃ riːtʃt riːtʃt/', 'Regular.', '[]'::jsonb, '[{"surface":"reach","pos":"verb","ipa":"/riːtʃ/","gloss":"alcançar, chegar a"},{"surface":"reached","pos":"verb","ipa":"/riːtʃt/","gloss":"alcançou"},{"surface":"reached","pos":"verb","ipa":"/riːtʃt/","gloss":"alcançou"}]'::jsonb, 'We reached the hotel at midnight.', 'Chegamos ao hotel à meia-noite.'),
  ('unit-essential-verbs-a1-54-09', 'lesson-essential-verbs-a1-54', 9, 'verb_forms', 'kill killed killed', 'matar', '/kɪl kɪld kɪld/', 'Regular.', '[]'::jsonb, '[{"surface":"kill","pos":"verb","ipa":"/kɪl/","gloss":"matar"},{"surface":"killed","pos":"verb","ipa":"/kɪld/","gloss":"matou"},{"surface":"killed","pos":"verb","ipa":"/kɪld/","gloss":"matou"}]'::jsonb, 'The storm killed the plants.', 'A tempestade matou as plantas.'),
  ('unit-essential-verbs-a1-54-10', 'lesson-essential-verbs-a1-54', 10, 'verb_forms', 'remain remained remained', 'permanecer', '/rɪˈmeɪn rɪˈmeɪnd rɪˈmeɪnd/', 'Regular.', '[]'::jsonb, '[{"surface":"remain","pos":"verb","ipa":"/rɪˈmeɪn/","gloss":"permanecer"},{"surface":"remained","pos":"verb","ipa":"/rɪˈmeɪnd/","gloss":"permaneceu"},{"surface":"remained","pos":"verb","ipa":"/rɪˈmeɪnd/","gloss":"permaneceu"}]'::jsonb, 'He remained calm.', 'Ele se manteve calmo.')
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-55-01', 'lesson-essential-verbs-a1-55', 1, 'sentence', 'They sell fresh bread here.', 'Eles vendem pão fresco aqui.', '/ðeɪ sɛl frɛʃ brɛd hɪr/', '"Sell" = vender.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"sell","pos":"verb","ipa":"/sɛl/","gloss":"vender"},{"surface":"fresh","pos":"adjective","ipa":"/frɛʃ/","gloss":"fresco"},{"surface":"bread","pos":"noun","ipa":"/brɛd/","gloss":"pão"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-55-02', 'lesson-essential-verbs-a1-55', 2, 'sentence', 'I sold my old car.', 'Vendi meu carro velho.', '/aɪ soʊld maɪ oʊld kɑːr/', 'Passado irregular: "sold".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"sold","pos":"verb","ipa":"/soʊld/","gloss":"vendeu"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-55-03', 'lesson-essential-verbs-a1-55', 3, 'sentence', 'Will you sell your house?', 'Você vai vender sua casa?', '/wɪl juː sɛl jʊr haʊs/', 'Pergunta com "will".', '[]'::jsonb, '[{"surface":"Will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"sell","pos":"verb","ipa":"/sɛl/","gloss":"vender"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"house","pos":"noun","ipa":"/haʊs/","gloss":"casa"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-55-04', 'lesson-essential-verbs-a1-55', 4, 'sentence', 'The tickets have sold out.', 'Os ingressos esgotaram.', '/ðə ˈtɪkɪts hæv soʊld aʊt/', '"Sell out" = esgotar.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"tickets","pos":"noun","ipa":"/ˈtɪkɪts/","gloss":"ingressos"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"sold","pos":"verb","ipa":"/soʊld/","gloss":"vendeu"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-55-05', 'lesson-essential-verbs-a1-55', 5, 'sentence', 'We eat dinner at seven.', 'Jantamos às sete.', '/wiː iːt ˈdɪnər æt ˈsɛvən/', '"Eat dinner" = jantar.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"eat","pos":"verb","ipa":"/iːt/","gloss":"comer"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-55-06', 'lesson-essential-verbs-a1-55', 6, 'sentence', 'I ate too much.', 'Comi demais.', '/aɪ eɪt tuː mʌtʃ/', 'Passado irregular: "ate" /eɪt/.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"ate","pos":"verb","ipa":"/eɪt/","gloss":"comeu"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-55-07', 'lesson-essential-verbs-a1-55', 7, 'sentence', 'Let''s eat out tonight.', 'Vamos comer fora hoje à noite.', '/lɛts iːt aʊt təˈnaɪt/', '"Eat out" = comer fora.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"eat","pos":"verb","ipa":"/iːt/","gloss":"comer"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"tonight","pos":"adverb","ipa":"/təˈnaɪt/","gloss":"hoje à noite"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-55-08', 'lesson-essential-verbs-a1-55', 8, 'sentence', 'Have you eaten yet?', 'Você já comeu?', '/hæv juː ˈiːtən jɛt/', 'Particípio irregular: "eaten".', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"eaten","pos":"verb","ipa":"/ˈiːtən/","gloss":"comido"},{"surface":"yet","pos":"adverb","ipa":"/jɛt/","gloss":"ainda"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-56-01', 'lesson-essential-verbs-a1-56', 1, 'sentence', 'I drink two liters of water a day.', 'Bebo dois litros de água por dia.', '/aɪ drɪŋk tuː ˈliːtərz ʌv ˈwɔːtər ə deɪ/', '"A day" = por dia.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"drink","pos":"verb","ipa":"/drɪŋk/","gloss":"beber"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"liters","pos":"noun","ipa":"/ˈliːtərz/","gloss":"litros"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-56-02', 'lesson-essential-verbs-a1-56', 2, 'sentence', 'We drank wine at dinner.', 'Bebemos vinho no jantar.', '/wiː dræŋk waɪn æt ˈdɪnər/', 'Passado irregular: "drank".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"drank","pos":"verb","ipa":"/dræŋk/","gloss":"bebeu"},{"surface":"wine","pos":"noun","ipa":"/waɪn/","gloss":"vinho"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-56-03', 'lesson-essential-verbs-a1-56', 3, 'sentence', 'I won''t drink tonight.', 'Não vou beber hoje à noite.', '/aɪ woʊnt drɪŋk təˈnaɪt/', 'Futuro negativo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"won''t","pos":"modal verb","ipa":"/woʊnt/","gloss":"não vai (will not)"},{"surface":"drink","pos":"verb","ipa":"/drɪŋk/","gloss":"beber"},{"surface":"tonight","pos":"adverb","ipa":"/təˈnaɪt/","gloss":"hoje à noite"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-56-04', 'lesson-essential-verbs-a1-56', 4, 'sentence', 'I''ve never drunk coffee.', 'Nunca tomei café.', '/aɪv ˈnɛvər drʌŋk ˈkɔːfi/', 'Particípio irregular: "drunk".', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"drunk","pos":"verb","ipa":"/drʌŋk/","gloss":"bebido"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-56-05', 'lesson-essential-verbs-a1-56', 5, 'sentence', 'I sleep eight hours a night.', 'Durmo oito horas por noite.', '/aɪ sliːp eɪt aʊərz ə naɪt/', '"Sleep" = dormir.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"sleep","pos":"verb","ipa":"/sliːp/","gloss":"dormir"},{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"},{"surface":"hours","pos":"noun","ipa":"/aʊərz/","gloss":"horas"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-56-06', 'lesson-essential-verbs-a1-56', 6, 'sentence', 'I slept badly last night.', 'Dormi mal ontem à noite.', '/aɪ slɛpt ˈbædli læst naɪt/', 'Passado irregular: "slept". "Badly" = mal.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"slept","pos":"verb","ipa":"/slɛpt/","gloss":"dormiu"},{"surface":"badly","pos":"adverb","ipa":"/ˈbædli/","gloss":"mal"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-56-07', 'lesson-essential-verbs-a1-56', 7, 'sentence', 'You''ll sleep better tonight.', 'Você vai dormir melhor hoje.', '/juːl sliːp ˈbɛtər təˈnaɪt/', '"Better" = melhor.', '[]'::jsonb, '[{"surface":"You''ll","pos":"pronoun","ipa":"/juːl/","gloss":"você vai (you will)"},{"surface":"sleep","pos":"verb","ipa":"/sliːp/","gloss":"dormir"},{"surface":"better","pos":"adjective","ipa":"/ˈbɛtər/","gloss":"melhor"},{"surface":"tonight","pos":"adverb","ipa":"/təˈnaɪt/","gloss":"hoje à noite"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-56-08', 'lesson-essential-verbs-a1-56', 8, 'sentence', 'I haven''t slept at all.', 'Não dormi nada.', '/aɪ ˈhævənt slɛpt æt ɔːl/', '"Not at all" = nada, de jeito nenhum.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"slept","pos":"verb","ipa":"/slɛpt/","gloss":"dormiu"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-57-01', 'lesson-essential-verbs-a1-57', 1, 'sentence', 'I drive to work.', 'Vou de carro para o trabalho.', '/aɪ draɪv tuː wɜːrk/', '"Drive to" = ir dirigindo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"drive","pos":"verb","ipa":"/draɪv/","gloss":"dirigir"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-57-02', 'lesson-essential-verbs-a1-57', 2, 'sentence', 'She drove all night.', 'Ela dirigiu a noite toda.', '/ʃiː droʊv ɔːl naɪt/', 'Passado irregular: "drove".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"drove","pos":"verb","ipa":"/droʊv/","gloss":"dirigiu"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-57-03', 'lesson-essential-verbs-a1-57', 3, 'sentence', 'I''ll drive you home.', 'Eu te levo para casa.', '/aɪl draɪv juː hoʊm/', '"Drive someone home" = levar de carro.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"drive","pos":"verb","ipa":"/draɪv/","gloss":"dirigir"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-57-04', 'lesson-essential-verbs-a1-57', 4, 'sentence', 'I''ve never driven in the snow.', 'Nunca dirigi na neve.', '/aɪv ˈnɛvər ˈdrɪvən ɪn ðə snoʊ/', 'Particípio irregular: "driven".', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"driven","pos":"verb","ipa":"/ˈdrɪvən/","gloss":"dirigido"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"snow","pos":"verb","ipa":"/snoʊ/","gloss":"nevar; neve"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-57-05', 'lesson-essential-verbs-a1-57', 5, 'sentence', 'Birds fly south in winter.', 'Os pássaros voam para o sul no inverno.', '/bɜːrdz flaɪ saʊθ ɪn ˈwɪntər/', '"Fly" = voar.', '[]'::jsonb, '[{"surface":"Birds","pos":"noun","ipa":"/bɜːrdz/","gloss":"pássaros"},{"surface":"fly","pos":"verb","ipa":"/flaɪ/","gloss":"voar"},{"surface":"south","pos":"noun","ipa":"/saʊθ/","gloss":"sul"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"winter","pos":"noun","ipa":"/ˈwɪntər/","gloss":"inverno"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-57-06', 'lesson-essential-verbs-a1-57', 6, 'sentence', 'We flew to Lisbon.', 'Voamos para Lisboa.', '/wiː fluː tuː ˈlɪzbən/', 'Passado irregular: "flew".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"flew","pos":"verb","ipa":"/fluː/","gloss":"voou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"Lisbon","pos":"proper noun","ipa":"/ˈlɪzbən/","gloss":"Lisboa"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-57-07', 'lesson-essential-verbs-a1-57', 7, 'sentence', 'Time will fly.', 'O tempo vai voar.', '/taɪm wɪl flaɪ/', 'Futuro com "will".', '[]'::jsonb, '[{"surface":"Time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"fly","pos":"verb","ipa":"/flaɪ/","gloss":"voar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-57-08', 'lesson-essential-verbs-a1-57', 8, 'sentence', 'Have you ever flown business class?', 'Você já voou de executiva?', '/hæv juː ˈɛvər floʊn ˈbɪznəs klæs/', 'Particípio irregular: "flown".', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"ever","pos":"adverb","ipa":"/ˈɛvər/","gloss":"alguma vez, já"},{"surface":"flown","pos":"verb","ipa":"/floʊn/","gloss":"voado"},{"surface":"business","pos":"noun","ipa":"/ˈbɪznəs/","gloss":"negócio, empresa"},{"surface":"class","pos":"noun","ipa":"/klæs/","gloss":"aula, turma"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-58-01', 'lesson-essential-verbs-a1-58', 1, 'sentence', 'I swim every morning.', 'Nado toda manhã.', '/aɪ swɪm ˈɛvri ˈmɔːrnɪŋ/', '"Swim" = nadar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"swim","pos":"verb","ipa":"/swɪm/","gloss":"nadar"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-58-02', 'lesson-essential-verbs-a1-58', 2, 'sentence', 'We swam in the ocean.', 'Nadamos no mar.', '/wiː swæm ɪn ðə ˈoʊʃən/', 'Passado irregular: "swam".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"swam","pos":"verb","ipa":"/swæm/","gloss":"nadou"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"ocean","pos":"noun","ipa":"/ˈoʊʃən/","gloss":"oceano, mar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-58-03', 'lesson-essential-verbs-a1-58', 3, 'sentence', 'I''ll swim after lunch.', 'Vou nadar depois do almoço.', '/aɪl swɪm ˈæftər lʌntʃ/', 'Futuro com "will".', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"swim","pos":"verb","ipa":"/swɪm/","gloss":"nadar"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"lunch","pos":"noun","ipa":"/lʌntʃ/","gloss":"almoço"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-58-04', 'lesson-essential-verbs-a1-58', 4, 'sentence', 'I haven''t swum in years.', 'Não nado há anos.', '/aɪ ˈhævənt swʌm ɪn jɪrz/', 'Particípio irregular: "swum".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"swum","pos":"verb","ipa":"/swʌm/","gloss":"nadado"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-58-05', 'lesson-essential-verbs-a1-58', 5, 'sentence', 'She sings in a band.', 'Ela canta numa banda.', '/ʃiː sɪŋz ɪn ə bænd/', '"Sing" = cantar.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"sings","pos":"verb","ipa":"/sɪŋz/","gloss":"canta"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"band","pos":"noun","ipa":"/bænd/","gloss":"banda"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-58-06', 'lesson-essential-verbs-a1-58', 6, 'sentence', 'We sang happy birthday.', 'Cantamos parabéns.', '/wiː sæŋ ˈhæpi ˈbɜːrθdeɪ/', 'Passado irregular: "sang".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"sang","pos":"verb","ipa":"/sæŋ/","gloss":"cantou"},{"surface":"happy","pos":"adjective","ipa":"/ˈhæpi/","gloss":"feliz"},{"surface":"birthday","pos":"noun","ipa":"/ˈbɜːrθdeɪ/","gloss":"aniversário"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-58-07', 'lesson-essential-verbs-a1-58', 7, 'sentence', 'Will you sing for us?', 'Você canta para a gente?', '/wɪl juː sɪŋ fɔːr ʌs/', 'Pedido com "will".', '[]'::jsonb, '[{"surface":"Will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"sing","pos":"verb","ipa":"/sɪŋ/","gloss":"cantar"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-58-08', 'lesson-essential-verbs-a1-58', 8, 'sentence', 'He has sung on many stages.', 'Ele já cantou em muitos palcos.', '/hiː hæz sʌŋ ɑːn ˈmɛni ˈsteɪdʒɪz/', 'Particípio irregular: "sung". Sequência i-a-u: sing, sang, sung.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"sung","pos":"verb","ipa":"/sʌŋ/","gloss":"cantado"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"stages","pos":"noun","ipa":"/ˈsteɪdʒɪz/","gloss":"palcos"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-59-01', 'lesson-essential-verbs-a1-59', 1, 'sentence', 'I always forget his birthday.', 'Sempre esqueço o aniversário dele.', '/aɪ ˈɔːlweɪz fərˈɡɛt hɪz ˈbɜːrθdeɪ/', '"Forget" = esquecer.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"forget","pos":"verb","ipa":"/fərˈɡɛt/","gloss":"esquecer"},{"surface":"his","pos":"determiner","ipa":"/hɪz/","gloss":"dele"},{"surface":"birthday","pos":"noun","ipa":"/ˈbɜːrθdeɪ/","gloss":"aniversário"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-59-02', 'lesson-essential-verbs-a1-59', 2, 'sentence', 'I forgot my umbrella.', 'Esqueci meu guarda-chuva.', '/aɪ fərˈɡɑːt maɪ ʌmˈbrɛlə/', 'Passado irregular: "forgot".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"forgot","pos":"verb","ipa":"/fərˈɡɑːt/","gloss":"esqueceu"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"umbrella","pos":"noun","ipa":"/ʌmˈbrɛlə/","gloss":"guarda-chuva"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-59-03', 'lesson-essential-verbs-a1-59', 3, 'sentence', 'Don''t worry, I won''t forget.', 'Não se preocupe, não vou esquecer.', '/doʊnt ˈwɜːri aɪ woʊnt fərˈɡɛt/', 'Promessa com "won''t".', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"worry","pos":"verb","ipa":"/ˈwɜːri/","gloss":"se preocupar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"won''t","pos":"modal verb","ipa":"/woʊnt/","gloss":"não vai (will not)"},{"surface":"forget","pos":"verb","ipa":"/fərˈɡɛt/","gloss":"esquecer"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-59-04', 'lesson-essential-verbs-a1-59', 4, 'sentence', 'I''ve forgotten the password.', 'Esqueci a senha.', '/aɪv fərˈɡɑːtən ðə ˈpæswɜːrd/', 'Particípio irregular: "forgotten".', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"forgotten","pos":"verb","ipa":"/fərˈɡɑːtən/","gloss":"esquecido"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"password","pos":"noun","ipa":"/ˈpæswɜːrd/","gloss":"senha"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-59-05', 'lesson-essential-verbs-a1-59', 5, 'sentence', 'I choose my own clothes.', 'Eu escolho minhas roupas.', '/aɪ tʃuːz maɪ oʊn kloʊðz/', '"Choose" = escolher.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"choose","pos":"verb","ipa":"/tʃuːz/","gloss":"escolher"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"own","pos":"verb","ipa":"/oʊn/","gloss":"ser dono, responsável"},{"surface":"clothes","pos":"noun","ipa":"/kloʊðz/","gloss":"roupas"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-59-06', 'lesson-essential-verbs-a1-59', 6, 'sentence', 'She chose the red one.', 'Ela escolheu o vermelho.', '/ʃiː tʃoʊz ðə rɛd wʌn/', 'Passado irregular: "chose".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"chose","pos":"verb","ipa":"/tʃoʊz/","gloss":"escolheu"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"red","pos":"adjective","ipa":"/rɛd/","gloss":"vermelho"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-59-07', 'lesson-essential-verbs-a1-59', 7, 'sentence', 'You will choose the next movie.', 'Você vai escolher o próximo filme.', '/juː wɪl tʃuːz ðə nɛkst ˈmuːvi/', 'Futuro com "will".', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"choose","pos":"verb","ipa":"/tʃuːz/","gloss":"escolher"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"movie","pos":"noun","ipa":"/ˈmuːvi/","gloss":"filme"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-59-08', 'lesson-essential-verbs-a1-59', 8, 'sentence', 'Have you chosen a name?', 'Vocês já escolheram um nome?', '/hæv juː ˈtʃoʊzən ə neɪm/', 'Particípio irregular: "chosen".', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"chosen","pos":"verb","ipa":"/ˈtʃoʊzən/","gloss":"escolhido"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-60-01', 'lesson-essential-verbs-a1-60', 1, 'verb_forms', 'sell sold sold', 'vender', '/sɛl soʊld soʊld/', 'Base "sell" · passado e particípio "sold".', '[]'::jsonb, '[{"surface":"sell","pos":"verb","ipa":"/sɛl/","gloss":"vender"},{"surface":"sold","pos":"verb","ipa":"/soʊld/","gloss":"vendeu"},{"surface":"sold","pos":"verb","ipa":"/soʊld/","gloss":"vendeu"}]'::jsonb, 'I sold my old car.', 'Vendi meu carro velho.'),
  ('unit-essential-verbs-a1-60-02', 'lesson-essential-verbs-a1-60', 2, 'verb_forms', 'eat ate eaten', 'comer', '/iːt eɪt ˈiːtən/', 'Base "eat" · passado "ate" · particípio "eaten".', '[]'::jsonb, '[{"surface":"eat","pos":"verb","ipa":"/iːt/","gloss":"comer"},{"surface":"ate","pos":"verb","ipa":"/eɪt/","gloss":"comeu"},{"surface":"eaten","pos":"verb","ipa":"/ˈiːtən/","gloss":"comido"}]'::jsonb, 'I ate too much.', 'Comi demais.'),
  ('unit-essential-verbs-a1-60-03', 'lesson-essential-verbs-a1-60', 3, 'verb_forms', 'drink drank drunk', 'beber', '/drɪŋk dræŋk drʌŋk/', 'Sequência i-a-u: drink, drank, drunk.', '[]'::jsonb, '[{"surface":"drink","pos":"verb","ipa":"/drɪŋk/","gloss":"beber"},{"surface":"drank","pos":"verb","ipa":"/dræŋk/","gloss":"bebeu"},{"surface":"drunk","pos":"verb","ipa":"/drʌŋk/","gloss":"bebido"}]'::jsonb, 'We drank wine at dinner.', 'Bebemos vinho no jantar.'),
  ('unit-essential-verbs-a1-60-04', 'lesson-essential-verbs-a1-60', 4, 'verb_forms', 'sleep slept slept', 'dormir', '/sliːp slɛpt slɛpt/', 'Base "sleep" · passado e particípio "slept".', '[]'::jsonb, '[{"surface":"sleep","pos":"verb","ipa":"/sliːp/","gloss":"dormir"},{"surface":"slept","pos":"verb","ipa":"/slɛpt/","gloss":"dormiu"},{"surface":"slept","pos":"verb","ipa":"/slɛpt/","gloss":"dormiu"}]'::jsonb, 'I slept badly last night.', 'Dormi mal ontem à noite.'),
  ('unit-essential-verbs-a1-60-05', 'lesson-essential-verbs-a1-60', 5, 'verb_forms', 'drive drove driven', 'dirigir', '/draɪv droʊv ˈdrɪvən/', 'Base "drive" · passado "drove" · particípio "driven".', '[]'::jsonb, '[{"surface":"drive","pos":"verb","ipa":"/draɪv/","gloss":"dirigir"},{"surface":"drove","pos":"verb","ipa":"/droʊv/","gloss":"dirigiu"},{"surface":"driven","pos":"verb","ipa":"/ˈdrɪvən/","gloss":"dirigido"}]'::jsonb, 'She drove all night.', 'Ela dirigiu a noite toda.'),
  ('unit-essential-verbs-a1-60-06', 'lesson-essential-verbs-a1-60', 6, 'verb_forms', 'fly flew flown', 'voar', '/flaɪ fluː floʊn/', 'Base "fly" · passado "flew" · particípio "flown".', '[]'::jsonb, '[{"surface":"fly","pos":"verb","ipa":"/flaɪ/","gloss":"voar"},{"surface":"flew","pos":"verb","ipa":"/fluː/","gloss":"voou"},{"surface":"flown","pos":"verb","ipa":"/floʊn/","gloss":"voado"}]'::jsonb, 'We flew to Lisbon.', 'Voamos para Lisboa.'),
  ('unit-essential-verbs-a1-60-07', 'lesson-essential-verbs-a1-60', 7, 'verb_forms', 'swim swam swum', 'nadar', '/swɪm swæm swʌm/', 'Sequência i-a-u: swim, swam, swum.', '[]'::jsonb, '[{"surface":"swim","pos":"verb","ipa":"/swɪm/","gloss":"nadar"},{"surface":"swam","pos":"verb","ipa":"/swæm/","gloss":"nadou"},{"surface":"swum","pos":"verb","ipa":"/swʌm/","gloss":"nadado"}]'::jsonb, 'We swam in the ocean.', 'Nadamos no mar.'),
  ('unit-essential-verbs-a1-60-08', 'lesson-essential-verbs-a1-60', 8, 'verb_forms', 'sing sang sung', 'cantar', '/sɪŋ sæŋ sʌŋ/', 'Sequência i-a-u: sing, sang, sung.', '[]'::jsonb, '[{"surface":"sing","pos":"verb","ipa":"/sɪŋ/","gloss":"cantar"},{"surface":"sang","pos":"verb","ipa":"/sæŋ/","gloss":"cantou"},{"surface":"sung","pos":"verb","ipa":"/sʌŋ/","gloss":"cantado"}]'::jsonb, 'We sang happy birthday.', 'Cantamos parabéns.'),
  ('unit-essential-verbs-a1-60-09', 'lesson-essential-verbs-a1-60', 9, 'verb_forms', 'forget forgot forgotten', 'esquecer', '/fərˈɡɛt fərˈɡɑːt fərˈɡɑːtən/', 'Base "forget" · passado "forgot" · particípio "forgotten".', '[]'::jsonb, '[{"surface":"forget","pos":"verb","ipa":"/fərˈɡɛt/","gloss":"esquecer"},{"surface":"forgot","pos":"verb","ipa":"/fərˈɡɑːt/","gloss":"esqueceu"},{"surface":"forgotten","pos":"verb","ipa":"/fərˈɡɑːtən/","gloss":"esquecido"}]'::jsonb, 'I forgot my umbrella.', 'Esqueci meu guarda-chuva.'),
  ('unit-essential-verbs-a1-60-10', 'lesson-essential-verbs-a1-60', 10, 'verb_forms', 'choose chose chosen', 'escolher', '/tʃuːz tʃoʊz ˈtʃoʊzən/', 'Base "choose" · passado "chose" · particípio "chosen".', '[]'::jsonb, '[{"surface":"choose","pos":"verb","ipa":"/tʃuːz/","gloss":"escolher"},{"surface":"chose","pos":"verb","ipa":"/tʃoʊz/","gloss":"escolheu"},{"surface":"chosen","pos":"verb","ipa":"/ˈtʃoʊzən/","gloss":"escolhido"}]'::jsonb, 'She chose the red one.', 'Ela escolheu o vermelho.')
